import yaml, glob

sources = glob.glob('docs/domain/sources/*.yaml')
for s in sorted(sources):
    with open(s, 'r', encoding='utf-8') as f:
        d = yaml.safe_load(f)
    keys = list(d.keys()) if isinstance(d, dict) else []
    counts = {}
    for k in keys:
        if isinstance(d[k], list):
            counts[k] = len(d[k])
    print(f'{s}: {counts}')
